/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * Memory layout for the raw image (docs/DESIGN-NOTES.md, M0d).
 *
 * IMAGE: the code window. The image's first byte is at its start and is
 *   the first instruction run (HW-1); the window shows the flash chip from
 *   offset 0x4000, so an image may be up to 1 MiB less 16 KiB (HW-5).
 * RAM: main RAM is 512 KiB from 0x01C00000 on the chip (HW-6). Its top,
 *   from 0x01C7FC00, is left alone: the block r0 points to at entry
 *   (HW-4), the SDK's boot and update area, and the vector table (HW-6,
 *   HW-18). fwtest has more RAM (HW-7); this layout uses only what the
 *   chip has.
 */

OUTPUT_ARCH(pi32v2)
ENTRY(_start)

MEMORY
{
    IMAGE (rx)  : ORIGIN = 0x02000000, LENGTH = 0x000FC000
    RAM   (rwx) : ORIGIN = 0x01C00000, LENGTH = 0x0007FC00
}

STACK_SIZE = 0x1000;

SECTIONS
{
    .text : {
        KEEP(*(.text.entry))
        *(.text .text.*)
        *(.rodata .rodata.*)
        . = ALIGN(4);
    } > IMAGE

    /* Fixed at the start of RAM so the tests know where it is. */
    .beacon (NOLOAD) : {
        __bss_start = .;
        KEEP(*(.beacon))
    } > RAM

    .bss (NOLOAD) : {
        *(.bss .bss.*)
        . = ALIGN(4);
        __bss_end = .;
    } > RAM

    /* Runs from RAM, loaded from the image just after the code. */
    .data : {
        __data_start = .;
        *(.data .data.*)
        . = ALIGN(4);
        __data_end = .;
    } > RAM AT > IMAGE
    __data_load = LOADADDR(.data);

    /* The stack takes the top of RAM and grows down from __stack_top. */
    __stack_top = ORIGIN(RAM) + LENGTH(RAM);
    __stack_limit = __stack_top - STACK_SIZE;

    ASSERT(ADDR(.beacon) == 0x01C00000, "the beacon must start main RAM")
    ASSERT(__data_end <= __stack_limit, "data and bss run into the stack")
    ASSERT(__stack_top == 0x01C7FC00, "the stack must end below the reserved top of RAM")
    ASSERT(__stack_top % 8 == 0, "the stack must be 8-byte aligned")

    /* Debug information: kept in the ELF, never loaded. Every section is
     * placed by name (the build links with --orphan-handling=error). */
    .debug_info     0 : { *(.debug_info) }
    .debug_abbrev   0 : { *(.debug_abbrev) }
    .debug_line     0 : { *(.debug_line) }
    .debug_str      0 : { *(.debug_str) }
    .debug_loc      0 : { *(.debug_loc) }
    .debug_ranges   0 : { *(.debug_ranges) }
    .debug_frame    0 : { *(.debug_frame) }
    .debug_macinfo  0 : { *(.debug_macinfo) }
    .debug_pubnames 0 : { *(.debug_pubnames) }
    .debug_pubtypes 0 : { *(.debug_pubtypes) }

    /DISCARD/ : { *(.comment) }
}
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * The image's first instruction. Core 0 starts here with every register
 * but r0 at zero and no usable stack (HW-1, HW-2), so this sets the stack
 * pointer and hands over to C. Nothing else needs assembly yet.
 */

	.section .text.entry,"ax",@progbits
	.globl	_start
	.type	_start,@function
_start:
	/* r0 holds the loader's block pointer (HW-4); M0d doesn't use it. */
	r1 = __stack_top
	sp = r1
	call	sb_start

	/* sb_start never returns. If it ever did, stop on purpose: interrupts
	 * off and a jump to itself, which fwtest reports as a halt. */
	cli
.Lstop:
	goto	.Lstop
	.size	_start, .-_start
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * C runtime start: give C its initial memory, then run main. Called from
 * crt0.S on the stack it set up. The symbols come from firmware/app.ld.
 */

#include "sb.h"

extern u32 __data_load[], __data_start[], __data_end[];
extern u32 __bss_start[], __bss_end[];

void sb_start(void) __attribute__((noreturn));

void sb_start(void)
{
    const u32 *src = __data_load;
    u32 *dst;

    /* Initialised data: its bytes sit in the image, after the code. */
    for (dst = __data_start; dst < __data_end; dst++)
        *dst = *src++;

    /* Zero-initialised data. fwtest starts with RAM cleared, but a loader
     * on the chip makes no such promise. */
    for (dst = __bss_start; dst < __bss_end; dst++)
        *dst = 0;

    main();
}
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * Our own minimal runtime definitions. The firmware is built with
 * -nostdinc, so nothing here comes from a C library.
 */

#ifndef SB_H
#define SB_H

typedef unsigned char u8;
typedef unsigned int u32;

_Static_assert(sizeof(u32) == 4, "u32 is 32 bits");

/* The beacon: four words at the start of main RAM (firmware/app.ld) that
 * fwtest reads with --ram and --watchdog (HW-26). Tests depend on this
 * layout; change it only together with tests/fw/. */
struct sb_beacon {
    u32 marker;   /* SB_MARKER once main runs and startup checked out */
    u32 beats;    /* heartbeat: whole milliseconds since main started it */
    u32 ticks;    /* time base ticks since then, stored on every pass */
    u32 period;   /* ticks per heartbeat, for the tests to read */
};

#define SB_MARKER     0x44304253u  /* "SB0D" in memory order */
#define SB_MARKER_BAD 0x21444142u  /* "BAD!": startup left data wrong */

extern volatile struct sb_beacon sb_beacon;

int main(void) __attribute__((noreturn));

#endif
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * M0d's firmware: check that startup gave C its memory, write the marker,
 * then keep a heartbeat timed by TIMER4. No interrupts yet (M1).
 */

#include "sb.h"
#include "WL82.h"

/* HW-25: in fwtest each word written here is appended to the console. The
 * SDK declares DBG_MSG read-only (Q-5), so it is written through our own
 * pointer rather than the SDK's struct. */
#define DBG_MSG (*(volatile u32 *)0x01EEE244u)

/* HW-13: TIMER4 counts 24 MHz once CON bit 0 is set. */
#define TIMER4_RUN   0x1u
#define TICKS_PER_MS 24000u

volatile struct sb_beacon sb_beacon __attribute__((section(".beacon")));

/* One of each kind of C data, for main to check that sb_start copied and
 * cleared them. */
static volatile u32 data_probe = 0x5EED0001u;
static volatile u32 bss_probe;

static void console_write(const char *text, u32 words)
{
    while (words--) {
        const u8 *b = (const u8 *)text;
        DBG_MSG = (u32)b[0] | (u32)b[1] << 8 | (u32)b[2] << 16 | (u32)b[3] << 24;
        text += 4;
    }
}

int main(void)
{
    static const char hello[16] = "small-beeps M0d\n";
    u32 start, done;

    sb_beacon.period = TICKS_PER_MS;
    if (data_probe == 0x5EED0001u && bss_probe == 0) {
        sb_beacon.marker = SB_MARKER;
        console_write(hello, sizeof hello / 4);
    } else {
        sb_beacon.marker = SB_MARKER_BAD;
    }

    /* Only differences of CNT are used: its value when started, and its
     * response to writes, don't matter. Unsigned subtraction is right
     * across a wrap of the 32-bit count. */
    JL_TIMER4->CON = TIMER4_RUN;
    start = JL_TIMER4->CNT;
    done = 0;
    for (;;) {
        u32 now = JL_TIMER4->CNT - start;

        /* Count every whole period that has passed, so a pass that comes
         * late still leaves the right number of beats. */
        while (now - done >= TICKS_PER_MS) {
            done += TICKS_PER_MS;
            sb_beacon.beats++;
        }
        /* Storing on every pass also keeps core 0 busy, so fwtest's
         * captures land on time (docs/HARNESS.md, "Time"). */
        sb_beacon.ticks = now;
    }
}

